//! Mouth shapes over time, and the pure mapping from those onto a race's
//! morph targets.
//!
//! Vanilla ships a LIP block beside every voice line, generated by the
//! Creation Kit out of FaceFX and its `FonixData.cdf` speech database. A mod
//! that adds voice lines has to go through that same editor, and the path is
//! broken often enough in Special Edition that the community ships a mod to
//! repair the database file. Deriving the shapes from the audio removes the
//! editor from the loop, so a line with no LIP block animates exactly like a
//! vanilla one. That is the point of this module, and it is why nothing here
//! treats a vanilla line as a special case.
//!
//! A [`VisemeSource`] produces a [`VisemeTrack`], and [`morph_weights`] turns
//! its shapes into weights on the morph targets a [`Race`] names. Native LIP
//! files already store target weights, exposed by [`crate::LipWeightTrack`]
//! without converting them into the nine Rhubarb shapes.

use soe_esm::records::race::Race;

use crate::error::Result;
use crate::pcm::Pcm;

/// One of the mouth positions Rhubarb Lip Sync emits: six basic shapes from
/// the Hanna-Barbera set plus three extended ones.
///
/// The sounds behind each shape are Rhubarb's own, from its `README.adoc`,
/// and they are what [`Shape::phoneme`] maps onto the FaceFX phoneme list.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Shape {
    /// Closed mouth, for P, B and M.
    A,
    /// Slightly open with clenched teeth, most consonants and the EE vowel.
    B,
    /// Open mouth, EH as in men and AE as in bat.
    C,
    /// Wide open, AA as in father.
    D,
    /// Slightly rounded, AO as in off and ER as in bird.
    E,
    /// Puckered, UW as in you, OW as in show and W as in way.
    F,
    /// Upper teeth on the lower lip, F and V. Extended shape.
    G,
    /// Tongue raised for a long L. Extended shape.
    H,
    /// Idle, the rest position between words. Extended shape.
    X,
}

impl Shape {
    /// Every shape, in the order Rhubarb documents them.
    pub const ALL: [Shape; 9] = [
        Shape::A,
        Shape::B,
        Shape::C,
        Shape::D,
        Shape::E,
        Shape::F,
        Shape::G,
        Shape::H,
        Shape::X,
    ];

    /// Parses the single letter Rhubarb writes in its output.
    #[must_use]
    pub fn from_letter(c: char) -> Option<Shape> {
        Some(match c.to_ascii_uppercase() {
            'A' => Shape::A,
            'B' => Shape::B,
            'C' => Shape::C,
            'D' => Shape::D,
            'E' => Shape::E,
            'F' => Shape::F,
            'G' => Shape::G,
            'H' => Shape::H,
            'X' => Shape::X,
            _ => return None,
        })
    }

    /// The letter Rhubarb writes for this shape.
    #[must_use]
    pub fn letter(self) -> char {
        match self {
            Shape::A => 'A',
            Shape::B => 'B',
            Shape::C => 'C',
            Shape::D => 'D',
            Shape::E => 'E',
            Shape::F => 'F',
            Shape::G => 'G',
            Shape::H => 'H',
            Shape::X => 'X',
        }
    }

    /// The FaceFX phoneme whose row in a race's `PHWT` block stands for this
    /// shape.
    ///
    /// Rhubarb's shapes are mouth positions and a race's mapping is keyed by
    /// phoneme, so one of the sounds Rhubarb lists for each shape has to
    /// stand for the group. The choice is taken straight from Rhubarb's own
    /// description of each shape, and every name here appears in
    /// [`soe_esm::records::race::PHONEMES`]. Keeping the weights themselves
    /// on the race record is what makes a dragon's face differ from a Nord's
    /// without any of that knowledge living here.
    #[must_use]
    pub fn phoneme(self) -> &'static str {
        match self {
            Shape::A => "M",
            Shape::B => "K",
            Shape::C => "EH",
            Shape::D => "AA",
            Shape::E => "AO",
            Shape::F => "UW",
            Shape::G => "F",
            Shape::H => "L",
            Shape::X => "SIL",
        }
    }
}

/// One shape held over a span of the recording. Rhubarb writes the end of
/// each cue as the start of the next, so spans tile the whole file.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MouthCue {
    pub start: f64,
    pub end: f64,
    pub shape: Shape,
}

/// A whole line's worth of mouth shapes.
///
/// This carries generated Rhubarb cues. Native LIP samples use
/// [`crate::LipWeightTrack`] to preserve their stored target weights.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct VisemeTrack {
    /// Seconds, as the producer reported it.
    pub duration: f64,
    /// In start order, non-overlapping.
    pub cues: Vec<MouthCue>,
}

impl VisemeTrack {
    /// The shape held at `seconds`, or the rest position outside the track.
    #[must_use]
    pub fn shape_at(&self, seconds: f64) -> Shape {
        self.cues
            .iter()
            .find(|c| seconds >= c.start && seconds < c.end)
            .map_or(Shape::X, |c| c.shape)
    }

    /// The shapes active at `seconds` with weights summing to one.
    ///
    /// A cue boundary is a hard cut in the file. Holding one for `blend`
    /// seconds into the next crossfades it instead, which is what a face
    /// needs and what the vanilla engine's own curves do. A `blend` of zero
    /// gives the cut back exactly.
    #[must_use]
    pub fn shapes_at(&self, seconds: f64, blend: f64) -> Vec<(Shape, f32)> {
        let current = self.shape_at(seconds);
        if blend <= 0.0 {
            return vec![(current, 1.0)];
        }
        let Some(i) = self
            .cues
            .iter()
            .position(|c| seconds >= c.start && seconds < c.end)
        else {
            return vec![(Shape::X, 1.0)];
        };
        let cue = self.cues[i];
        let into = seconds - cue.start;
        if into >= blend || i == 0 {
            return vec![(current, 1.0)];
        }
        let previous = self.cues[i - 1].shape;
        if previous == current {
            return vec![(current, 1.0)];
        }
        // Linear is enough: the cues are already quantised to hundredths of a
        // second, so a smoother curve would be shaping noise.
        let t = (into / blend) as f32;
        vec![(previous, 1.0 - t), (current, t)]
    }
}

/// Anything that can turn a decoded line into mouth shapes.
///
/// The engine holds one of these rather than calling a particular tool.
/// Native LIP decoding instead uses [`crate::Lip::decode`].
pub trait VisemeSource {
    /// `dialog` is the line's written text when it is known. The recognizer
    /// uses it to constrain what it is listening for, so passing it sharpens
    /// the result and passing `None` still works.
    ///
    /// # Errors
    ///
    /// [`crate::Error::Decode`] when the source fails or is unavailable.
    fn visemes(&self, pcm: &Pcm, dialog: Option<&str>) -> Result<VisemeTrack>;
}

/// Persistent cache for tracks generated from an audio asset.
///
/// The cache key combines the asset bytes and a caller-provided canonical
/// description of every generation input. This keeps a changed dialogue or
/// recogniser configuration from reusing a track generated under old inputs.
/// The cache directory is separate from source assets so a BSA extraction or
/// a read-only mod directory can use a writable cache root.
#[derive(Debug, Clone)]
pub struct VisemeCache {
    directory: std::path::PathBuf,
}

impl VisemeCache {
    /// Creates a cache rooted at directory.
    #[must_use]
    pub fn new(directory: impl Into<std::path::PathBuf>) -> Self {
        Self {
            directory: directory.into(),
        }
    }

    /// Creates a cache directory beside an asset.
    #[must_use]
    pub fn beside(asset: &std::path::Path) -> Self {
        let parent = asset.parent().unwrap_or_else(|| std::path::Path::new("."));
        Self::new(parent.join(".soe-visemes"))
    }

    /// Returns a generated track from the cache, or generates and stores it.
    ///
    /// Asset bytes work for both loose files and virtual files read from an
    /// archive. Settings must include every value that can alter generation.
    ///
    /// # Errors
    ///
    /// Returns an I/O error when the cache cannot be read or written, and
    /// returns the error from generate when generation fails.
    pub fn get_or_generate(
        &self,
        asset: &[u8],
        settings: &str,
        generate: impl FnOnce() -> Result<VisemeTrack>,
    ) -> Result<VisemeTrack> {
        let asset_key = cache_hash(asset);
        let settings_key = cache_hash(settings.as_bytes());
        let path = self
            .directory
            .join(format!("{asset_key:016x}-{settings_key:016x}.viseme"));

        match std::fs::read_to_string(&path) {
            Ok(text) => {
                if let Some(track) = decode_cached_track(&text, asset_key, settings_key) {
                    return Ok(track);
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }

        let track = generate()?;
        std::fs::create_dir_all(&self.directory)?;
        let temporary = self.directory.join(format!(
            ".{asset_key:016x}-{settings_key:016x}-{}-{}.tmp",
            std::process::id(),
            cache_nonce()
        ));
        std::fs::write(
            &temporary,
            encode_cached_track(&track, asset_key, settings_key),
        )?;
        std::fs::rename(temporary, path)?;
        Ok(track)
    }
}

pub(crate) fn cache_hash(bytes: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn cache_nonce() -> u64 {
    use std::sync::atomic::{AtomicU64, Ordering};

    static NEXT: AtomicU64 = AtomicU64::new(0);
    NEXT.fetch_add(1, Ordering::Relaxed)
}

fn encode_cached_track(track: &VisemeTrack, asset_key: u64, settings_key: u64) -> String {
    let mut text = format!(
        "SOE-VISEME-CACHE 1\n{asset_key:016x}\n{settings_key:016x}\n{:016x}\n{}\n",
        track.duration.to_bits(),
        track.cues.len()
    );
    for cue in &track.cues {
        text.push_str(&format!(
            "{:016x} {:016x} {}\n",
            cue.start.to_bits(),
            cue.end.to_bits(),
            cue.shape.letter()
        ));
    }
    text
}

fn decode_cached_track(text: &str, asset_key: u64, settings_key: u64) -> Option<VisemeTrack> {
    const MAX_CACHED_CUES: usize = 1_000_000;

    let mut lines = text.lines();
    if lines.next()? != "SOE-VISEME-CACHE 1"
        || u64::from_str_radix(lines.next()?, 16).ok()? != asset_key
        || u64::from_str_radix(lines.next()?, 16).ok()? != settings_key
    {
        return None;
    }
    let duration = f64::from_bits(u64::from_str_radix(lines.next()?, 16).ok()?);
    if !duration.is_finite() || duration < 0.0 {
        return None;
    }
    let count = lines.next()?.parse::<usize>().ok()?;
    if count > MAX_CACHED_CUES || count > lines.clone().count() {
        return None;
    }
    let mut cues = Vec::with_capacity(count);
    let mut previous_end = 0.0;
    for _ in 0..count {
        let mut parts = lines.next()?.split_ascii_whitespace();
        let start = f64::from_bits(u64::from_str_radix(parts.next()?, 16).ok()?);
        let end = f64::from_bits(u64::from_str_radix(parts.next()?, 16).ok()?);
        let token = parts.next()?;
        let mut letters = token.chars();
        let shape = letters.next().and_then(Shape::from_letter)?;
        if letters.next().is_some()
            || parts.next().is_some()
            || !start.is_finite()
            || !end.is_finite()
            || start < previous_end
            || start >= end
            || end > duration
        {
            return None;
        }
        previous_end = end;
        cues.push(MouthCue { start, end, shape });
    }
    if lines.next().is_some() {
        return None;
    }
    Some(VisemeTrack { duration, cues })
}

/// The race whose phoneme mapping should drive an actor's face.
///
/// Vanilla writes the mapping on six races out of ninety nine: the four with
/// eight `Lip` prefixed targets are the dragons and the hagraven, and the two
/// with the sixteen humanoid targets are `WerewolfBeastRace` and
/// `dunMiddenEmptyRace`. Every playable race, `NordRace` included, carries
/// none at all, so reading only the actor's own race leaves almost every face
/// in the game still. The humanoid table does exist in the file, just not on
/// the races that need it, so a caller resolves through a donor that has one.
/// Which donor is the caller's policy, not this crate's.
#[must_use]
pub fn mapping_race<'a>(actor: &'a Race, donor: &'a Race) -> &'a Race {
    if actor.phoneme_mapping_is_complete() {
        actor
    } else {
        donor
    }
}

/// Weights on a race's morph targets for a set of weighted shapes.
///
/// Pure, so it is tested without a renderer: shapes in, named target weights
/// out. Each shape contributes its race row scaled by its own weight, and
/// rows are summed, which is what blending two shapes across a cue boundary
/// means. A shape whose phoneme the race never wrote contributes nothing
/// rather than zeroing the face.
#[must_use]
pub fn morph_weights<'a>(shapes: &[(Shape, f32)], race: &'a Race) -> Vec<(&'a str, f32)> {
    let mut out: Vec<(&str, f32)> = race
        .phoneme_targets
        .iter()
        .map(|n| (n.as_str(), 0.0))
        .collect();
    for (shape, weight) in shapes {
        let Some(row) = race.weights_for(shape.phoneme()) else {
            continue;
        };
        for (slot, value) in out.iter_mut().zip(row.iter()) {
            slot.1 += value * weight;
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::{morph_weights, MouthCue, Shape, VisemeTrack};
    use soe_esm::plugin::Record;
    use soe_esm::records::race::{Race, PHONEMES};
    use soe_esm::tag;

    fn track() -> VisemeTrack {
        VisemeTrack {
            duration: 0.47,
            cues: vec![
                MouthCue {
                    start: 0.0,
                    end: 0.05,
                    shape: Shape::X,
                },
                MouthCue {
                    start: 0.05,
                    end: 0.27,
                    shape: Shape::D,
                },
                MouthCue {
                    start: 0.27,
                    end: 0.47,
                    shape: Shape::B,
                },
            ],
        }
    }

    /// A race whose row for phoneme `i` is `[i, 0, 0]`, so a weight can be
    /// read straight back as the phoneme index.
    fn race() -> Race {
        let mut rec = Record::new(tag::RACE, 1).zsub(tag::EDID, "TestRace");
        for name in ["Aah", "BMP", "Oh"] {
            rec = rec.zsub(b"PHTN", name);
        }
        for i in 0..PHONEMES.len() {
            let row: Vec<u8> = [i as f32, 0.0, 0.0]
                .iter()
                .flat_map(|f| f.to_le_bytes())
                .collect();
            rec = rec.sub(b"PHWT", row);
        }
        Race::from_record(&rec).unwrap()
    }

    fn cache_test_directory() -> std::path::PathBuf {
        use std::sync::atomic::{AtomicU64, Ordering};

        static NEXT: AtomicU64 = AtomicU64::new(0);
        let number = NEXT.fetch_add(1, Ordering::Relaxed);
        std::env::temp_dir().join(format!(
            "soe-viseme-cache-test-{}-{number}",
            std::process::id()
        ))
    }

    #[test]
    fn a_repeated_request_reuses_the_cached_track() {
        use super::VisemeCache;

        let directory = cache_test_directory();
        std::fs::create_dir_all(&directory).unwrap();
        let asset = directory.join("line.wav");
        std::fs::write(&asset, b"voice line").unwrap();
        let cache = VisemeCache::beside(&asset);
        let generated = std::cell::Cell::new(0);
        let expected = track();

        let first = cache
            .get_or_generate(
                &std::fs::read(&asset).unwrap(),
                "rhubarb=1.14.0\ndialog=Hi",
                || {
                    generated.set(generated.get() + 1);
                    Ok(expected.clone())
                },
            )
            .unwrap();
        let second = cache
            .get_or_generate(
                &std::fs::read(&asset).unwrap(),
                "rhubarb=1.14.0\ndialog=Hi",
                || {
                    generated.set(generated.get() + 1);
                    Ok(VisemeTrack::default())
                },
            )
            .unwrap();

        assert_eq!(first, expected);
        assert_eq!(second, expected);
        assert_eq!(generated.get(), 1);
        std::fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn changed_generation_settings_invalidate_a_cached_track() {
        use super::VisemeCache;

        let directory = cache_test_directory();
        std::fs::create_dir_all(&directory).unwrap();
        let asset = directory.join("line.wav");
        std::fs::write(&asset, b"voice line").unwrap();
        let cache = VisemeCache::beside(&asset);
        let generated = std::cell::Cell::new(0);

        let first = cache
            .get_or_generate(
                &std::fs::read(&asset).unwrap(),
                "rhubarb=1.14.0\ndialog=Hi",
                || {
                    generated.set(generated.get() + 1);
                    Ok(track())
                },
            )
            .unwrap();
        let second = cache
            .get_or_generate(
                &std::fs::read(&asset).unwrap(),
                "rhubarb=1.14.0\ndialog=Hello",
                || {
                    generated.set(generated.get() + 1);
                    Ok(VisemeTrack::default())
                },
            )
            .unwrap();

        assert_eq!(first, track());
        assert_eq!(second, VisemeTrack::default());
        assert_eq!(generated.get(), 2);
        std::fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn changed_asset_bytes_invalidate_a_cached_track() {
        use super::VisemeCache;

        let directory = cache_test_directory();
        std::fs::create_dir_all(&directory).unwrap();
        let asset = directory.join("line.wav");
        std::fs::write(&asset, b"first voice line").unwrap();
        let cache = VisemeCache::beside(&asset);
        let generated = std::cell::Cell::new(0);

        cache
            .get_or_generate(&std::fs::read(&asset).unwrap(), "rhubarb=1.14.0", || {
                generated.set(generated.get() + 1);
                Ok(track())
            })
            .unwrap();
        std::fs::write(&asset, b"replacement voice line").unwrap();
        let replacement = VisemeTrack::default();
        let second = cache
            .get_or_generate(&std::fs::read(&asset).unwrap(), "rhubarb=1.14.0", || {
                generated.set(generated.get() + 1);
                Ok(replacement.clone())
            })
            .unwrap();

        assert_eq!(second, replacement);
        assert_eq!(generated.get(), 2);
        std::fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn malformed_cache_records_are_misses() {
        let asset_key = super::cache_hash(b"asset");
        let settings_key = super::cache_hash(b"settings");
        let header = format!(
            "SOE-VISEME-CACHE 1\n{asset_key:016x}\n{settings_key:016x}\n3ff0000000000000\n1\n"
        );
        assert!(super::decode_cached_track(
            &(header.clone() + "0000000000000000 3ff0000000000000 A\ntrailing"),
            asset_key,
            settings_key
        )
        .is_none());
        assert!(super::decode_cached_track(
            &(header.clone() + "7ff8000000000000 3ff0000000000000 A"),
            asset_key,
            settings_key
        )
        .is_none());
        assert!(super::decode_cached_track(
            &(header + "0000000000000000 3ff0000000000000 AXYZ"),
            asset_key,
            settings_key
        )
        .is_none());
    }

    #[test]
    fn a_letter_round_trips_through_the_shape() {
        for s in Shape::ALL {
            assert_eq!(Shape::from_letter(s.letter()), Some(s));
        }
        assert_eq!(Shape::from_letter('q'), None);
    }

    #[test]
    fn every_shape_names_a_phoneme_a_race_actually_carries() {
        for s in Shape::ALL {
            assert!(
                PHONEMES.contains(&s.phoneme()),
                "{} maps to {}, which is not a FaceFX phoneme",
                s.letter(),
                s.phoneme()
            );
        }
    }

    #[test]
    fn the_track_reads_back_its_shapes_and_rests_outside() {
        let t = track();
        assert_eq!(t.shape_at(0.0), Shape::X);
        assert_eq!(t.shape_at(0.1), Shape::D);
        assert_eq!(t.shape_at(0.3), Shape::B);
        assert_eq!(t.shape_at(9.0), Shape::X);
    }

    #[test]
    fn a_blend_crossfades_across_a_cue_boundary() {
        let t = track();
        // No blend is the hard cut the file describes.
        assert_eq!(t.shapes_at(0.06, 0.0), vec![(Shape::D, 1.0)]);
        // Halfway into a 0.04 s blend, both shapes are half weight.
        let mixed = t.shapes_at(0.07, 0.04);
        assert_eq!(mixed.len(), 2);
        assert_eq!(mixed[0].0, Shape::X);
        assert_eq!(mixed[1].0, Shape::D);
        assert!((mixed[0].1 - 0.5).abs() < 1e-6);
        assert!((mixed[1].1 - 0.5).abs() < 1e-6);
        // Past the blend window only the current shape is left.
        assert_eq!(t.shapes_at(0.2, 0.04), vec![(Shape::D, 1.0)]);
    }

    #[test]
    fn morph_weights_scale_the_races_own_rows() {
        let race = race();
        // D maps to AA, index 5 in the phoneme order.
        let w = morph_weights(&[(Shape::D, 1.0)], &race);
        assert_eq!(w[0].0, "Aah");
        assert!((w[0].1 - 5.0).abs() < 1e-6);
        // Two shapes at half weight sum: AA is 5, K is 38.
        let w = morph_weights(&[(Shape::D, 0.5), (Shape::B, 0.5)], &race);
        assert!((w[0].1 - f32::midpoint(5.0, 38.0)).abs() < 1e-5);
        // Targets the race names are all present even at rest.
        let w = morph_weights(&[(Shape::X, 1.0)], &race);
        assert_eq!(w.len(), 3);
        assert_eq!(
            w.iter().map(|(n, _)| *n).collect::<Vec<_>>(),
            ["Aah", "BMP", "Oh"]
        );
    }

    #[test]
    fn a_race_with_no_mapping_resolves_through_the_donor() {
        use super::mapping_race;
        let donor = race();
        let empty = Race::from_record(&Record::new(tag::RACE, 2)).unwrap();
        assert_eq!(mapping_race(&empty, &donor).form_id, donor.form_id);
        assert_eq!(mapping_race(&donor, &empty).form_id, donor.form_id);
    }

    #[test]
    fn a_race_without_the_phoneme_contributes_nothing() {
        let rec = Record::new(tag::RACE, 1).zsub(b"PHTN", "Aah");
        let race = Race::from_record(&rec).unwrap();
        let w = morph_weights(&[(Shape::D, 1.0)], &race);
        assert_eq!(w, [("Aah", 0.0)]);
    }
}
